-- Real-export regression cases run before the original pipeline's first Apply.
-- bulk_source is populated only from the real exporter archives through the
-- unchanged Node reader; no edits to staged rows, manifests or finished runs.
-- Add 20 assertions to that same pgTAP file, no separate runner.
create function pg_temp.bulk_call(device uuid,session uuid,device_hash text,session_hash text,op text,p jsonb) returns jsonb language sql as $$
 select app_private.payment_history_local_baseline_request_v2(
  '10000000-0000-4000-8000-000000003019',device,'30000000-0000-4000-8000-000000003019',session,
  device_hash,session_hash,7,op,p)->'result';
$$;
create function pg_temp.exercise_bulk_source(scenario text) returns jsonb language plpgsql as $$
declare f jsonb;d uuid;s uuid:=gen_random_uuid();credential uuid:=gen_random_uuid();upload uuid:=gen_random_uuid();
 device_hash text:='sha256:'||encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex');
 session_hash text:='sha256:'||encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex');
 started jsonb;lease jsonb;review jsonb;receipt jsonb;replay jsonb;case_apply_key uuid:=gen_random_uuid();answer jsonb;
 before_count bigint;before_native bigint;before_revision bigint;before_changes bigint;
begin
 select value into strict f from pg_temp.bulk_source where name=scenario;
 d:=(f#>>'{manifest,deviceId}')::uuid;
 begin
  -- The mixed case uses an original, normally committed baseline to provide
  -- five canonical identities, then submits another genuine six-fact source.
  if scenario='mixed' then
   perform pg_temp.baseline('apply',seed.value) from pg_temp.baseline_context seed where seed.key='apply_payload';
  end if;
  select count(*) into before_count from public.payment_history_movement_versions where shop_id='10000000-0000-4000-8000-000000003019';
  select count(*) into before_native from public.pos_sales where shop_id='10000000-0000-4000-8000-000000003019';
  select revision into before_revision from public.payment_history_runtime where shop_id='10000000-0000-4000-8000-000000003019';
  select count(*) into before_changes from public.payment_history_change_sets where shop_id='10000000-0000-4000-8000-000000003019';
  insert into public.shop_devices(shop_device_id,shop_id,device_identifier,display_name,device_type,status)
   values(d,'10000000-0000-4000-8000-000000003019','SYNTHETIC-BULK-'||scenario,'Synthetic bulk source','pos','active');
  insert into public.pos_device_credentials(pos_device_credential_id,shop_id,shop_device_id,staff_id,token_hash,staff_credential_version,expires_at)
   values(credential,'10000000-0000-4000-8000-000000003019',d,'30000000-0000-4000-8000-000000003019',device_hash,7,clock_timestamp()+interval '1 hour');
  insert into public.pos_sessions(pos_session_id,shop_id,shop_device_id,staff_id,pos_device_credential_id,session_token_hash,staff_credential_version,issued_at,expires_at)
   values(s,'10000000-0000-4000-8000-000000003019',d,'30000000-0000-4000-8000-000000003019',credential,session_hash,7,clock_timestamp()-interval '1 minute',clock_timestamp()+interval '30 minutes');
  insert into public.payment_history_uploads(upload_id,shop_id,actor_kind,actor_id,object_key,file_name,file_sha256,byte_length,state,verified_at)
   values(upload,'10000000-0000-4000-8000-000000003019','pos_staff_manager','30000000-0000-4000-8000-000000003019',
    'history/10000000-0000-4000-8000-000000003019/'||upload,'synthetic-bulk.w7history.zip',f->>'archiveSha256',(f->>'byteLength')::bigint,'verified',clock_timestamp());
  started:=pg_temp.bulk_call(d,s,device_hash,session_hash,'start',jsonb_build_object('request_key',gen_random_uuid(),'upload_id',upload,
   'local_dataset_id',f#>>'{manifest,localDatasetId}','data_revision',f#>>'{manifest,dataRevision}',
   'restore_epoch',f#>>'{manifest,restoreEpoch}','restore_lineage_id',f#>>'{manifest,restoreLineageId}','writer_epoch','1'));
  lease:=public.payment_history_migration_worker_v1('claim','{}')->'run';
  if lease->>'run_id' is distinct from started->>'run_id' then raise exception 'bulk_fixture_claim_mismatch';end if;
  if jsonb_array_length(f->'objects')>0 then
   perform public.payment_history_migration_worker_v1('stage_objects',jsonb_build_object('run_id',lease->>'run_id','lease_token',lease->>'lease_token','lease_fence',lease->>'lease_fence','rows',f->'objects'));
  end if;
  if jsonb_array_length(f->'movements')>0 then
   perform public.payment_history_migration_worker_v1('stage_movements',jsonb_build_object('run_id',lease->>'run_id','lease_token',lease->>'lease_token','lease_fence',lease->>'lease_fence','rows',f->'movements'));
  end if;
  perform public.payment_history_migration_worker_v1('finish',jsonb_build_object('run_id',lease->>'run_id','lease_token',lease->>'lease_token','lease_fence',lease->>'lease_fence','raw_manifest',f->>'rawManifest','analysis_digest',f->>'analysisDigest'));
  review:=pg_temp.bulk_call(d,s,device_hash,session_hash,'review',jsonb_build_object('run_id',started->>'run_id'));
  if review->>'can_apply' is distinct from 'true' then raise exception 'bulk_fixture_review_not_applicable';end if;
  receipt:=pg_temp.bulk_call(d,s,device_hash,session_hash,'apply',jsonb_build_object('run_id',started->>'run_id','request_key',case_apply_key,'review_digest',review->>'review_digest'));
  replay:=pg_temp.bulk_call(d,s,device_hash,session_hash,'apply',jsonb_build_object('run_id',started->>'run_id','request_key',case_apply_key,'review_digest',review->>'review_digest'));
  answer:=jsonb_build_object(
   'receiptCounts',jsonb_build_array(receipt->'new_active',receipt->'new_inactive',receipt->'duplicates',receipt->'new_batches'),
   'replayIdentical',receipt=replay,
   'baselineVerified',receipt#>>'{baseline_context,state}'='baseline_verified',
   'newVersionCount',(select count(*)-before_count from public.payment_history_movement_versions where shop_id='10000000-0000-4000-8000-000000003019'),
   'mapCount',(select count(*) from public.payment_history_local_movement_map where shop_id='10000000-0000-4000-8000-000000003019' and shop_device_id=d),
   'ownedMapCount',(select count(*) from public.payment_history_local_movement_map where shop_id='10000000-0000-4000-8000-000000003019' and shop_device_id=d and owns_version),
   'duplicateCount',(select count(*) from public.payment_history_duplicate_observations where shop_id='10000000-0000-4000-8000-000000003019'),
   'mapParity',(select count(*)=jsonb_array_length(f->'movements') and coalesce(bool_and(m.source_economic_digest=x.economic_digest and m.source_fact_digest=encode(extensions.digest(convert_to((o.object-'is_active')::text,'UTF8'),'sha256'),'hex')
     and v.economic_digest=x.economic_digest and v.business_ticks=(x.economics->>'businessTicks')::bigint
     and v.active=x.active and v.gross_clp=(x.economics->>'grossClp')::bigint
     and v.commission_clp is not distinct from (x.economics->>'commissionClp')::bigint
     and v.commission_vat_clp is not distinct from (x.economics->>'commissionVatClp')::bigint
     and v.net_clp is not distinct from (x.economics->>'netClp')::bigint),true)
    from public.payment_history_local_movement_map m
    join public.payment_history_movement_versions v on v.shop_id=m.shop_id and v.movement_version_id=m.movement_version_id
    join public.payment_history_migration_movements x on x.run_id=(started->>'run_id')::uuid and x.local_id=m.local_movement_id
    join public.payment_history_migration_objects o on o.run_id=x.run_id and o.table_name='movements' and o.local_id=x.local_id
    where m.shop_id='10000000-0000-4000-8000-000000003019' and m.shop_device_id=d),
   'supersedesCount',(select count(*) from public.payment_history_migration_movements x where x.run_id=(started->>'run_id')::uuid and x.supersedes_local_id is not null),
   'supersedesParity',(select count(*)=(select count(*) from public.payment_history_migration_movements where run_id=(started->>'run_id')::uuid and supersedes_local_id is not null)
    and coalesce(bool_and(coalesce(v.supersedes_version_id=previous.movement_version_id and v.active and not previous_version.active and v.identity_key=previous_version.identity_key,false)),true)
    from public.payment_history_migration_movements x
    join public.payment_history_local_movement_map current_map on current_map.shop_id=x.shop_id and current_map.shop_device_id=d and current_map.local_dataset_id=f#>>'{manifest,localDatasetId}' and current_map.local_movement_id=x.local_id
    join public.payment_history_local_movement_map previous on previous.shop_id=x.shop_id and previous.shop_device_id=d and previous.local_dataset_id=f#>>'{manifest,localDatasetId}' and previous.local_movement_id=x.supersedes_local_id
    join public.payment_history_movement_versions v on v.shop_id=current_map.shop_id and v.movement_version_id=current_map.movement_version_id
    join public.payment_history_movement_versions previous_version on previous_version.shop_id=previous.shop_id and previous_version.movement_version_id=previous.movement_version_id
    where x.run_id=(started->>'run_id')::uuid and x.supersedes_local_id is not null),
   'supersedesEconomicChanges',(select count(*) from public.payment_history_migration_movements current_source
    join public.payment_history_migration_movements previous_source on previous_source.run_id=current_source.run_id and previous_source.local_id=current_source.supersedes_local_id
    where current_source.run_id=(started->>'run_id')::uuid and current_source.economic_digest<>previous_source.economic_digest),
   'rawObjectParity',(select count(*)=jsonb_array_length(f->'objects') and coalesce(bool_and(o.original_object=x.object and o.object_digest=x.object_digest),true)
    from public.payment_history_source_objects o join public.payment_history_migration_objects x on x.run_id=(started->>'run_id')::uuid and x.table_name=o.table_name and x.local_id=o.local_id
    where o.shop_id='10000000-0000-4000-8000-000000003019' and o.source_snapshot_id=(receipt->>'source_snapshot_id')::uuid),
   'oneRevision',(select revision=before_revision+1 from public.payment_history_runtime where shop_id='10000000-0000-4000-8000-000000003019'),
   'oneChangeSet',(select count(*)=before_changes+1 from public.payment_history_change_sets where shop_id='10000000-0000-4000-8000-000000003019'),
   'nativeUnchanged',(select count(*)=before_native from public.pos_sales where shop_id='10000000-0000-4000-8000-000000003019')
  );
  -- Roll back the entire case, including the mixed case's normal seed Apply.
  -- PL/pgSQL retains local answer while rolling back database effects.
  raise exception using errcode='P0199',message='synthetic_bulk_case_complete_rollback';
 exception when sqlstate 'P0199' then return answer;
 end;
end;$$;
create temp table bulk_results(name text primary key,value jsonb);
insert into bulk_results select name,pg_temp.exercise_bulk_source(name) from bulk_source order by name;
select is((select count(*)::integer from bulk_results),5,'all five real-export semantic scenarios completed');
select is((select value->'receiptCounts' from bulk_results where name='active'),'[5,0,0,1]'::jsonb,'new active source has exact receipt counts');
select is((select value->'receiptCounts' from bulk_results where name='inactive'),'[0,5,0,1]'::jsonb,'new inactive source stays inactive and owned');
select is((select value->'receiptCounts' from bulk_results where name='empty'),'[0,0,0,0]'::jsonb,'empty source publishes no invented financial fact');
select is((select value->'receiptCounts' from bulk_results where name='mixed'),'[1,0,5,2]'::jsonb,'mixed source uses ordered new-and-duplicate semantics');
select is((select value->'receiptCounts' from bulk_results where name='supersedes'),'[2,5,0,2]'::jsonb,'supersedes source keeps inactive predecessors and new active facts');
select ok((select bool_and((value->>'replayIdentical')::boolean) from bulk_results),'same-key replay returns each original receipt');
select ok((select bool_and((value->>'baselineVerified')::boolean) from bulk_results),'every original source binds its own verified baseline context');
select ok((select bool_and((value->>'mapParity')::boolean) from bulk_results),'all mappings preserve exact economics and source-fact digest');
select ok((select bool_and((value->>'rawObjectParity')::boolean) from bulk_results),'all original objects and operation receipts remain byte-derived provenance');
select ok((select bool_and((value->>'oneRevision')::boolean and (value->>'oneChangeSet')::boolean
 and (value->>'newVersionCount')::integer=(value#>>'{receiptCounts,0}')::integer+(value#>>'{receiptCounts,1}')::integer
 and value->>'newVersionCount'=value->>'ownedMapCount') from bulk_results),'each first Apply seals one revision with exactly the owned new facts and replay adds none');
select ok((select bool_and((value->>'nativeUnchanged')::boolean) from bulk_results),'all paths preserve native sales');
select is((select value->>'ownedMapCount' from bulk_results where name='active'),'5','all new active facts have owned maps');
select is((select value->>'ownedMapCount' from bulk_results where name='inactive'),'5','all new inactive facts have owned maps');
select is((select value->>'mapCount' from bulk_results where name='empty'),'0','empty source has no local movement maps');
select is((select value->>'ownedMapCount' from bulk_results where name='mixed'),'1','mixed source owns only its one new fact');
select is((select value->>'duplicateCount' from bulk_results where name='mixed'),'5','mixed source records five canonical duplicate observations');
select is((select jsonb_build_array(value->'supersedesCount',value->'supersedesEconomicChanges') from bulk_results where name='supersedes'),'[2,1]'::jsonb,'both reimports keep predecessors while only one changes economics');
select ok((select (value->>'supersedesParity')::boolean from bulk_results where name='supersedes'),'supersedes links to the original preceding mapped version');
select is((select count(*)::integer from public.payment_history_movement_versions where shop_id='10000000-0000-4000-8000-000000003019'),0,'all scenario database effects rolled back before the original pipeline Apply');

-- Fail after both insertion paths, then verify transactional rollback before
-- the original positive Apply. The CLR source, actor, review and digest remain intact.
create function pg_temp.baseline_apply_state() returns jsonb language plpgsql as $$
declare result jsonb:='{}';relation_name text;n bigint;begin
 for relation_name in select unnest(array[
  'payment_history_batches','payment_history_receipts','payment_history_movement_versions',
  'payment_history_local_batch_map','payment_history_local_movement_map',
  'payment_history_duplicate_observations','payment_history_source_snapshots',
  'payment_history_source_objects','payment_history_revisions','payment_history_replica_events',
  'payment_history_change_sets','payment_history_local_writer_contexts'
 ]) loop
  execute format('select count(*) from public.%I where shop_id=$1',relation_name)
   into n using '10000000-0000-4000-8000-000000003019'::uuid;
  result:=result||jsonb_build_object(relation_name,n);
 end loop;
 return result||jsonb_build_object(
  'runtime',(select to_jsonb(r) from public.payment_history_runtime r where r.shop_id='10000000-0000-4000-8000-000000003019'),
  'run',(select to_jsonb(r) from public.payment_history_migration_runs r join pg_temp.baseline_context c on r.run_id=(c.value->>'run_id')::uuid where c.key='start'),
  'decisions',(select count(*) from public.payment_history_migration_decisions d join pg_temp.baseline_context c on d.run_id=(c.value->>'run_id')::uuid where c.key='start')
 );
end;$$;
insert into baseline_context values('pre_apply_state',pg_temp.baseline_apply_state());
create function pg_temp.baseline_apply_fail_after_mapping() returns trigger language plpgsql as $$
begin
 if new.shop_id='10000000-0000-4000-8000-000000003019' then
  -- This marker is reached only after both real INSERT paths have completed.
  if (select count(*) from public.payment_history_movement_versions where shop_id=new.shop_id)<>5
   or (select count(*) from public.payment_history_local_movement_map where shop_id=new.shop_id and owns_version)<>5
   or (select count(*) from public.payment_history_migration_decisions where run_id=new.run_id and decision='new_active')<>5 then
   raise exception using errcode='P0192',message='baseline_rollback_probe_precondition_failed';
  end if;
  raise exception using errcode='P0191',message='baseline_rollback_after_five_versions_and_maps';
 end if;
 return new;
end;$$;
create trigger synthetic_baseline_apply_rollback_probe before insert on public.payment_history_source_snapshots
 for each row execute function pg_temp.baseline_apply_fail_after_mapping();
select throws_ok($$select pg_temp.baseline('apply',value) from baseline_context where key='apply_payload'$$,
 'P0191','baseline_rollback_after_five_versions_and_maps','failed Apply rolls back after actual new versions and local maps exist');
select is(pg_temp.baseline_apply_state(),(select value from baseline_context where key='pre_apply_state'),
 'failed Apply preserves the original review and leaves no financial, provenance, receipt, revision or replica changes');
drop trigger synthetic_baseline_apply_rollback_probe on public.payment_history_source_snapshots;


insert into baseline_context select 'receipt',pg_temp.baseline('apply',value) from baseline_context where key='apply_payload';

select ok((select value->>'new_active'='5' and value->>'new_inactive'='0' and value->>'duplicates'='0' from baseline_context where key='receipt')
 and (select count(*)=5 and bool_and(m.owns_version and m.source_fact_digest=encode(extensions.digest(convert_to((o.original_object-'is_active')::text,'UTF8'),'sha256'),'hex'))
  from public.payment_history_local_movement_map m
  join public.payment_history_local_writer_contexts c on c.shop_id=m.shop_id and c.shop_device_id=m.shop_device_id
  join public.payment_history_source_objects o on o.shop_id=c.shop_id and o.source_snapshot_id=c.source_snapshot_id and o.table_name='movements' and o.local_id=m.local_movement_id
  where m.shop_id='10000000-0000-4000-8000-000000003019'),
 'new-fact Apply keeps counters, ownership and the immutable original source-fact digest');

select is((select value#>>'{baseline_context,state}' from baseline_context where key='receipt'),'baseline_verified','canonical baseline and local context commit together');
select is((select c.restore_lineage_id::text from public.payment_history_local_writer_contexts c where c.shop_id='10000000-0000-4000-8000-000000003019'),(select value#>>'{manifest,restoreLineageId}' from baseline_context where key='fixture'),'canonical context preserves the actual CLR restore lineage');
select ok((select writer_authority='local' and writer_epoch=1 from public.payment_history_runtime where shop_id='10000000-0000-4000-8000-000000003019'),'baseline never performs frozen-to-local or web cutover');
select is((select pg_temp.baseline('apply',value) from baseline_context where key='apply_payload'),(select value from baseline_context where key='receipt'),'lost apply response recovers the same canonical receipt');
select ok((select revision=1 from public.payment_history_runtime where shop_id='10000000-0000-4000-8000-000000003019') and (select count(*)=5 from public.payment_history_movement_versions where shop_id='10000000-0000-4000-8000-000000003019'),'replay creates no second movement or revision');
select ok((select count(*)=5 and sum(v.gross_clp)=3380 and sum(v.net_clp)=3320 and bool_and(v.business_ticks=(o.original_object->>'business_ticks')::bigint and v.economic_digest=m.source_economic_digest and v.gross_clp=(o.original_object->>'signed_amount_clp')::bigint and v.net_clp is not distinct from (o.original_object->>'signed_net_clp')::bigint)
 from public.payment_history_local_movement_map m join public.payment_history_movement_versions v on v.shop_id=m.shop_id and v.movement_version_id=m.movement_version_id join public.payment_history_local_writer_contexts c on c.shop_id=m.shop_id and c.shop_device_id=m.shop_device_id join public.payment_history_source_objects o on o.shop_id=c.shop_id and o.source_snapshot_id=c.source_snapshot_id and o.table_name='movements' and o.local_id=m.local_movement_id where m.shop_id='10000000-0000-4000-8000-000000003019') and (select count(*)=0 from public.pos_sales where shop_id='10000000-0000-4000-8000-000000003019'),'identities, exact dates and CLP economics match the original CLR ledger without native sales');
-- A new source whose archive lineage differs from its authenticated admission
-- must fail before it can become another canonical source or context.
insert into baseline_context values('bad_start',pg_temp.baseline('start',pg_temp.start_payload('81000000-0000-4000-8000-000000003019')||'{"restore_lineage_id":"51000000-0000-4000-8000-000000003019"}'));
insert into baseline_context values('bad_lease',public.payment_history_migration_worker_v1('claim','{}')->'run');
do $$declare f jsonb;l jsonb;begin
 select value into f from baseline_context where key='fixture';select value into l from baseline_context where key='bad_lease';
 perform public.payment_history_migration_worker_v1('stage_objects',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','rows',f->'objects'));
 perform public.payment_history_migration_worker_v1('stage_movements',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','rows',f->'movements'));
end;$$;
select throws_ok($$select public.payment_history_migration_worker_v1('finish',jsonb_build_object('run_id',l.value->>'run_id','lease_token',l.value->>'lease_token','lease_fence',l.value->>'lease_fence','raw_manifest',f.value->>'rawManifest','analysis_digest',f.value->>'analysisDigest')) from baseline_context l cross join baseline_context f where l.key='bad_lease' and f.key='fixture'$$,'22023','payment_history_local_baseline_scope_mismatch','copied or stale source lineage cannot be admitted');
insert into public.staff_web_sessions(staff_web_session_id,shop_id,staff_id,session_token_hash,staff_credential_version,status,issued_at,expires_at)
 values('40000000-0000-4000-8000-000000003019','10000000-0000-4000-8000-000000003019','30000000-0000-4000-8000-000000003019','sha256:'||repeat('d',64),7,'active',clock_timestamp()-interval '1 minute',clock_timestamp()+interval '1 hour');
select throws_ok($$select public.payment_history_migration_request_v1('10000000-0000-4000-8000-000000003019','status',jsonb_build_object('run_id',value->>'run_id'),'30000000-0000-4000-8000-000000003019','40000000-0000-4000-8000-000000003019','sha256:'||repeat('d',64),7) from baseline_context where key='start'$$,'42501','payment_history_job_actor_mismatch','public frozen migration cannot take over a POS baseline');
insert into public.payment_history_local_write_grants(shop_id,shop_device_id,writer_epoch,operation_id,issued_at,expires_at)
 values('10000000-0000-4000-8000-000000003019','20000000-0000-4000-8000-000000003019',1,'91000000-0000-4000-8000-000000003019',clock_timestamp()-interval '2 minutes',clock_timestamp()-interval '90 seconds');
select throws_ok($$select pg_temp.baseline('start',pg_temp.start_payload('82000000-0000-4000-8000-000000003019'))$$,'40001','payment_history_local_baseline_outcome_unknown','expired legacy grant is not silently discarded by enrollment');
update public.pos_sessions set status='revoked',revoked_at=clock_timestamp() where pos_session_id='60000000-0000-4000-8000-000000003019';
select ok(not (select app_private.payment_history_migration_actor_current_v1(j) from public.payment_history_migration_runs j join baseline_context c on j.run_id=(c.value->>'run_id')::uuid where c.key='bad_start'),'worker observes POS revocation independently of web session');
select throws_ok($$select pg_temp.baseline('status',jsonb_build_object('run_id',value->>'run_id')) from baseline_context where key='start'$$,'42501','payment_history_device_denied','revoked POS cannot recover baseline data through web identity');
select is((select count(*)::integer from public.payment_history_movement_versions where shop_id='10000000-0000-4000-8000-000000003019'),5,'scope failures and revocation leave the committed baseline unchanged');
select * from finish();
rollback;
